    #[test]
    fn gui_profile_route_requires_every_fixed_phase_marker() {
        let phases = [
            "settled-settings",
            "home-pan-right",
            "home-pan-left",
            "arcade-scroll",
            "settled-arcade",
        ];
        let markers = phases
            .iter()
            .flat_map(|phase| {
                [
                    json!({"phase": phase, "event": "started"}),
                    json!({"phase": phase, "event": "presented"}),
                ]
            })
            .collect::<Vec<_>>();
        let passing = json!({
            "schema": "mister-magik-gui-profiling-window-v1",
            "state": "complete",
            "pmu_requested": false,
            "pmu_valid": true,
            "dropped_frame_records": 0,
            "phase_markers": markers,
        });
        validate_gui_profile_route(&passing, false).unwrap();
        let mut quality_failed = passing.clone();
        quality_failed["state"] = json!("failed");
        quality_failed["failure"] = Value::Null;
        quality_failed["dropped_frame_records"] = json!(3);
        validate_gui_profile_route(&quality_failed, false).unwrap();
        quality_failed["failure"] = json!("profiling route timed out");
        assert!(validate_gui_profile_route(&quality_failed, false).is_err());
        let mut missing = passing;
        missing["phase_markers"].as_array_mut().unwrap().pop();
        assert!(validate_gui_profile_route(&missing, false).is_err());
    }

    fn gui_attribution_test_route(pmu: bool, repeated_vblank_count: u64) -> Value {
        let markers = GUI_PROFILE_PHASES
            .iter()
            .enumerate()
            .flat_map(|(index, phase)| {
                let started = 1_000 + index as u64 * 1_000;
                [
                    json!({"phase": phase, "event": "started", "monotonic_us": started}),
                    json!({"phase": phase, "event": "presented", "monotonic_us": started + 500}),
                ]
            })
            .collect::<Vec<_>>();
        let records = if pmu {
            vec![json!({
                "name": "gui.slint-raster.ordinary",
                "counters": {
                    "time_enabled_ns": 100,
                    "time_running_ns": 100,
                    "counters": {
                        "cycles": 1_000,
                        "instructions": 750,
                        "l1d_accesses": 100,
                        "l1d_refills": 10,
                        "branches": 50,
                        "branch_mispredicts": 5,
                    },
                },
            })]
        } else {
            Vec::new()
        };
        let frames = [
            (1_u64, 2_000_u64, 1_u64, 0_u64),
            (2_u64, 20_000_u64, 2_u64, repeated_vblank_count),
        ]
        .into_iter()
        .map(|(frame, monotonic_us, sequence, repeated)| {
            json!({
                "frame": frame,
                "monotonic_us": monotonic_us,
                "phase": "home-pan-right",
                "slint_damage_rects": [[0, 0, 10, 10]],
                "latch": {
                    "invalid_bytes": 200,
                    "catchup_bytes": 0,
                    "copied_rectangles": 1,
                    "full_copy": false,
                },
                "presentation": {
                    "repeated_vblank_count": repeated,
                    "latch_drop_count": 0,
                    "ownership_loss_count": 0,
                    "active_sequence": sequence,
                },
            })
        })
        .collect::<Vec<_>>();
        json!({
            "schema": "mister-magik-gui-profile-route-v1",
            "pmu_requested": pmu,
            "profile": {
                "schema": "mister-magik-gui-profiling-window-v1",
                "state": "complete",
                "pmu_requested": pmu,
                "pmu_valid": true,
                "dropped_frame_records": 0,
                "measurement_started_at_us": 1_000,
                "measurement_ended_at_us": 6_000,
                "phase_markers": markers,
                "frames": frames,
                "thread_profile": {
                    "enabled": pmu,
                    "failure": null,
                    "dropped_spans": 0,
                    "records": records,
                },
            },
        })
    }

    #[test]
    fn gui_attribution_summary_separates_pmu_metrics_from_control_quality() {
        let control = gui_attribution_test_route(false, 0);
        let pmu = gui_attribution_test_route(true, 0);
        let streamline = gui_attribution_test_route(false, 0);
        let summary = summarize_gui_frame_attribution(&control, &pmu, &streamline).unwrap();
        assert_eq!(summary["artifact_validity"], "passed");
        assert_eq!(
            summary["control"]["presentation"]["quality_status"],
            "passed"
        );
        assert_eq!(
            summary["pmu"]["counters"]["total"]["cycles_per_frame"],
            500.0
        );
        assert_eq!(
            summary["pmu"]["counters"]["total"]["instructions_per_cycle"],
            0.75
        );
        assert_eq!(
            summary["control"]["copy_amplification"]["invalid_to_damage_ratio"],
            1.0
        );
    }

    #[test]
    fn gui_attribution_correlates_repeated_vblank_outliers_without_latch_drops() {
        let control = gui_attribution_test_route(false, 1);
        let pmu = gui_attribution_test_route(true, 0);
        let streamline = gui_attribution_test_route(false, 0);
        let summary = summarize_gui_frame_attribution(&control, &pmu, &streamline).unwrap();
        assert_eq!(
            summary["control"]["presentation"]["quality_status"],
            "failed"
        );
        assert_eq!(
            summary["control"]["presentation"]["physical_repeated_vblanks"],
            1
        );
        assert_eq!(summary["control"]["presentation"]["latch_drops"], 0);
        assert_eq!(
            summary["control"]["presentation"]["phase_outliers"][0]["physical_repeated_vblanks"],
            1
        );
    }

    #[test]
    fn launcher_response_streamline_integrity_rejects_each_failure_counter() {
        let fields = [
            "lost_actions",
            "duplicated_actions",
            "coalesced_actions",
            "reordered_actions",
            "proxy_write_failures",
            "journal_overflows",
            "sequence_gaps",
            "latch_drops",
            "ownership_losses",
        ];
        let mut route = serde_json::Map::new();
        for field in fields {
            route.insert(field.to_owned(), json!(0));
        }
        let passing = Value::Object(route);
        assert!(launcher_response_integrity_passed(&passing));
        for field in fields {
            let mut failed = passing.clone();
            failed[field] = json!(1);
            assert!(!launcher_response_integrity_passed(&failed), "{field}");
        }
    }

    #[test]
    fn launcher_response_attribution_arms_enable_only_their_owned_observer() {
        let control =
            launcher_response_attribution_env(LauncherResponseAttributionArm::Control, "run-1");
        let execution =
            launcher_response_attribution_env(LauncherResponseAttributionArm::Execution, "run-1");
        let pprof =
            launcher_response_attribution_env(LauncherResponseAttributionArm::Pprof, "run-1");
        let pmu = launcher_response_attribution_env(LauncherResponseAttributionArm::Pmu, "run-1");
        assert!(control.is_empty());
        assert_eq!(
            execution,
            vec![(
                "MISTER_LAUNCHER_RESPONSE_EXECUTION_TRACE".into(),
                "1".into()
            )]
        );
        assert!(
            pprof.iter().any(|(key, value)| {
                key == "MISTER_PPROF_TRIGGER" && value == "launcher-response"
            })
        );
        assert!(
            pprof
                .iter()
                .any(|(key, value)| { key == "MISTER_PPROF_HZ" && value == "997" })
        );
        assert!(pprof.iter().all(|(key, _)| key != "MISTER_PMU_PROFILE"));
        assert!(
            pmu.iter()
                .any(|(key, value)| { key == "MISTER_LAUNCHER_RESPONSE_PMU" && value == "1" })
        );
        assert!(
            pmu.iter()
                .any(|(key, value)| { key == "MISTER_PMU_RECORD_LIMIT" && value == "4096" })
        );
        assert!(pmu.iter().all(|(key, _)| key != "MISTER_PPROF"));
    }

