    #[test]
    fn startup_intro_cadence_and_latch_gates_cover_50_and_60_hz_routes() {
        let intro_frames =
            |period_us: u64, frame_count: u64, skip_at: Option<u64>, failure: Option<&str>| {
                (0_u64..frame_count)
                    .map(|frame| {
                        let skipped_us =
                            u64::from(skip_at.is_some_and(|at| frame >= at)) * period_us;
                        let failed = failure
                            .is_some_and(|kind| frame == frame_count / 2 && kind == "confirmation");
                        json!({
                        "frame": frame,
                        "completion_monotonic_us": 1_000_000 + frame * period_us + skipped_us,
                        "main_present_copy_path": "external-direct",
                        "main_present_status": if failed { "unsupported" } else { "ok" },
                        "main_present_sequence": (frame as u16).wrapping_add(1),
                        "main_present_active_sequence": if failed {
                            frame as u16
                        } else {
                            (frame as u16).wrapping_add(1)
                        },
                        "main_present_pending": false,
                        "main_present_flip_count": (frame as u16).wrapping_add(1),
                        "main_present_drop_count": u64::from(
                            failure == Some("drop") && frame + 1 == frame_count
                        ),
                        "main_present_completion_poll_count": 1,
                        "vsync_source": if failure == Some("pacing") && frame == frame_count / 2 {
                            "fallback"
                        } else {
                            "vsync"
                        },
                        "vsync_miss_streak": u64::from(
                            failure == Some("pacing") && frame == frame_count / 2
                        ),
                        "vsync_period_us": period_us,
                        })
                    })
                    .collect::<Vec<_>>()
            };
        let telemetry = |route: &str, width: u64, height: u64, frames, dropped_frames: u64| {
            vec![json!({
                "launcher": {
                    "catalog_refresh_policy": "force",
                    "output_route": route,
                    "framebuffer_width": width,
                    "framebuffer_height": height,
                    "startup_intro": {
                        "schema": "mister-magik-startup-intro-cadence-v1",
                        "source": "fpga-owned-vblank-telemetry",
                        "available": true,
                        "qualified": dropped_frames == 0,
                        "dropped_frames": dropped_frames
                    },
                    "frame_budget": {"recent_frames": frames}
                }
            })]
        };
        let display = |route: &str, width: u64, height: u64| {
            json!({
                "route": route,
                "framebuffer_width": width,
                "framebuffer_height": height,
            })
        };

        let passing_60 = summarize_startup_intro_telemetry(
            &telemetry(
                "crt-480p60",
                640,
                480,
                intro_frames(16_667, 1_200, None, None),
                0,
            ),
            &display("crt-480p60", 640, 480),
        )
        .unwrap();
        assert_eq!(passing_60["expected_frames"], 1_200);
        assert_eq!(passing_60["cadence"]["qualified"], true);
        assert_eq!(passing_60["latch_protocol"]["qualified"], true);
        assert_eq!(passing_60["particles"]["density"], "half");

        let passing_50 = summarize_startup_intro_telemetry(
            &telemetry(
                "crt-576p50",
                640,
                576,
                intro_frames(20_000, 1_000, None, None),
                0,
            ),
            &display("crt-576p50", 640, 576),
        )
        .unwrap();
        assert_eq!(passing_50["expected_frames"], 1_000);
        assert_eq!(passing_50["captured_frames"], 1_000);
        assert_eq!(passing_50["logical_elapsed_ms"], 20_000);
        assert_eq!(passing_50["cadence"]["qualified"], true);
        assert_eq!(passing_50["latch_protocol"]["qualified"], true);

        let dropped = summarize_startup_intro_telemetry(
            &telemetry(
                "crt-288p50",
                640,
                288,
                intro_frames(20_000, 1_000, None, None),
                1,
            ),
            &display("crt-288p50", 640, 288),
        )
        .unwrap();
        assert_eq!(dropped["cadence"]["qualified"], false);
        assert_eq!(dropped["cadence"]["dropped_frames"], 1);
        assert_eq!(dropped["latch_protocol"]["qualified"], true);
        assert_eq!(dropped["latch_protocol"]["latch_drop_delta"], 0);

        for failure in ["pacing", "confirmation", "drop"] {
            let failed = summarize_startup_intro_telemetry(
                &telemetry(
                    "crt-240p60",
                    640,
                    240,
                    intro_frames(16_667, 1_200, None, Some(failure)),
                    0,
                ),
                &display("crt-240p60", 640, 240),
            )
            .unwrap();
            if failure == "pacing" {
                assert_eq!(failed["cadence"]["qualified"], true);
                assert_eq!(failed["latch_protocol"]["qualified"], true);
            } else {
                assert_eq!(failed["cadence"]["qualified"], true);
                assert_eq!(failed["latch_protocol"]["qualified"], false);
            }
        }

        let software_disagreement = summarize_startup_intro_telemetry(
            &telemetry(
                "crt-480p60",
                640,
                480,
                intro_frames(16_667, 1_200, Some(600), None),
                0,
            ),
            &display("crt-480p60", 640, 480),
        )
        .unwrap();
        assert_eq!(software_disagreement["cadence"]["qualified"], true);
        assert_eq!(software_disagreement["cadence"]["dropped_frames"], 0);
        assert_eq!(
            software_disagreement["cadence"]["software_estimated_dropped_frames"],
            1
        );
        assert_eq!(software_disagreement["cadence"]["software_disagrees"], true);

        let mut unavailable = telemetry(
            "crt-480p60",
            640,
            480,
            intro_frames(16_667, 1_200, None, None),
            0,
        );
        unavailable[0]["launcher"]
            .as_object_mut()
            .unwrap()
            .remove("startup_intro");
        assert!(
            summarize_startup_intro_telemetry(&unavailable, &display("crt-480p60", 640, 480),)
                .is_err()
        );
    }

